/**
 * Gets the coordinate value currently entered in the given {@link InputTextView}.
 *
 * @param input The {@link InputTextView} to read.
 * @return The text of the input as a {@link Double}, or null if the input is empty or isn't a
 *         valid number.
 */
@Nullable
private Double getCoordinateInput(InputTextView input) {
    String inputText = input.getInputText();

    // getInputText() returns null for an empty input
    if (inputText == null)
        return null;

    inputText = inputText.replace(',', '.'); // some countries/keyboards use ',' in place of '.'

    // an input of "-" or "." alone isn't a coordinate yet
    if (inputText.equals("-") || inputText.equals(".") || inputText.equals("-."))
        return null;

    try {
        return (double)Utils.asFloat(inputText, 0);
    } catch (NumberFormatException e) {
        e.printStackTrace();
        return null;
    }
}

/**
 * @return True if the given latitude and longitude form a valid coordinate pair; false
 *         otherwise.
 */
private boolean isValidCoordinates(double latitude, double longitude) {
